"use strict";(globalThis.webpackChunkdoqumentation=globalThis.webpackChunkdoqumentation||[]).push([[96089],{34628(a,n,e){e.r(n),e.d(n,{assets:()=>s,contentTitle:()=>r,default:()=>d,frontMatter:()=>k,metadata:()=>i,toc:()=>m});const i=JSON.parse('{"id":"learning/courses/practical-near-term-qc/introduction","title":"Introduction","description":"Pengenalan kepada kursus tentang aplikasi praktikal pengkomputeran kuantum.","source":"@site/i18n/ms/docusaurus-plugin-content-docs/current/learning/courses/practical-near-term-qc/introduction.mdx","sourceDirName":"learning/courses/practical-near-term-qc","slug":"/learning/courses/practical-near-term-qc/introduction","permalink":"/learning/courses/practical-near-term-qc/introduction","draft":false,"unlisted":false,"editUrl":"https://github.com/JanLahmann/doQumentation/tree/main/docs/learning/courses/practical-near-term-qc/introduction.mdx","tags":[],"version":"current","frontMatter":{"description":"Pengenalan kepada kursus tentang aplikasi praktikal pengkomputeran kuantum.","notebook_path":"learning/courses/practical-near-term-qc/introduction.ipynb","sidebar_label":"Introduction","title":"Introduction"},"sidebar":"tutorialsSidebar","previous":{"title":"Pengkomputeran kuantum praktikal jangka terdekat","permalink":"/learning/courses/practical-near-term-qc/"},"next":{"title":"Gambaran keseluruhan","permalink":"/learning/courses/quantum-business-foundations/"}}');var t=e(74848),u=e(28453);const k={description:"Pengenalan kepada kursus tentang aplikasi praktikal pengkomputeran kuantum.",notebook_path:"learning/courses/practical-near-term-qc/introduction.ipynb",sidebar_label:"Introduction",title:"Introduction"},r="Pengenalan kepada pengkomputeran kuantum praktikal jangka dekat {#introduction-to-practical-near-term-quantum-computing}",s={},m=[{value:"Untuk apa komputer kuantum mungkin berguna",id:"what-quantum-computers-might-be-useful-for",level:2},{value:"Utiliti dan kelebihan kuantum jangka dekat",id:"near-term-quantum-utility-and-advantage",level:2},{value:"Asas ringkas dalam teori kerumitan",id:"a-brief-foundation-in-complexity-theory",level:2},{value:"Daripada teori kerumitan kepada bukti praktikal",id:"from-complexity-theory-to-practical-evidence",level:2},{value:"Bidang aplikasi dan kajian kes kursus",id:"application-areas-and-course-case-studies",level:2},{value:"Simulasi Hamiltonian",id:"hamiltonian-simulation",level:3},{value:"Pengoptimuman",id:"optimization",level:3},{value:"Pembelajaran mesin kuantum",id:"quantum-machine-learning",level:3},{value:"Persamaan pembezaan separa",id:"partial-differential-equations",level:3},{value:"Kesimpulan",id:"conclusion",level:2}];function l(a){const n={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",strong:"strong",ul:"ul",...(0,u.R)(),...a.components};return(0,t.jsxs)(t.Fragment,{children:["\n",(0,t.jsx)(n.header,{children:(0,t.jsx)(n.h1,{id:"introduction-to-practical-near-term-quantum-computing",children:"Pengenalan kepada pengkomputeran kuantum praktikal jangka dekat"})}),"\n",(0,t.jsx)(n.p,{children:"Sejak komputer kuantum pertama kali dicadangkan lebih empat dekad yang lalu, persoalannya ialah: Sejauh manakah pendekatan baharu ini dapat melanjutkan had pengkomputeran? Sains komputer teori memberikan kita beberapa jawapan yang menarik. Komputer kuantum dapat memfaktorkan integer besar dengan jauh lebih pantas daripada kaedah klasik terbaik yang diketahui, mempercepat carian tidak berstruktur, dan mensimulasikan sistem kuantum dengan lebih semula jadi. Namun, banyak idea ini mengandaikan komputer kuantum berskala besar yang bertoleransi terhadap kerosakan pada masa hadapan."}),"\n",(0,t.jsx)(n.p,{children:"Teknologi ini belum mencapai semua matlamat teori tersebut, tetapi ia bertambah baik dengan pesat. Penyelidik kini boleh menggunakan pemproses kuantum untuk meneroka masalah sains dan industri sebenar. Dalam kursus ini, kita akan mendapat pengalaman praktikal dengan beberapa aplikasi yang paling menjanjikan. Kita akan menganggar sifat tenaga rendah bagi model molekul yang kompleks, mensimulasikan dinamik teori tolok kekisi, dan meneroka bagaimana masalah portfolio kewangan boleh dipetakan kepada komputer kuantum. Kita juga akan melihat bidang yang lebih baharu yang kita baru mula memahami apa yang mungkin ditawarkan oleh komputer kuantum, termasuk pembelajaran mesin kuantum (QML) dan pendekatan kuantum terhadap persamaan pembezaan separa (PDE)."}),"\n",(0,t.jsx)(n.p,{children:"Banyak contoh dalam kursus ini cukup kecil untuk diselesaikan oleh komputer klasik. Ini disengajakan. Matlamatnya ialah memberikan anda pengalaman nyata dengan keseluruhan proses menggunakan komputer kuantum untuk menangani masalah dunia sebenar. Sesetengah contoh mewakili masalah yang kelebihan kuantum mungkin muncul pada skala yang jauh lebih besar. Dalam contoh lain, kita menggunakan kaedah yang dipermudahkan supaya butiran pelaksanaan tidak menyembunyikan idea kuantum yang utama."}),"\n",(0,t.jsx)(n.p,{children:"Menjelang akhir kursus, anda sepatutnya mempunyai gambaran keseluruhan tentang aplikasi kuantum utama dan gerak hati tentang mengapa komputer kuantum mungkin berguna dalam bidang tertentu. Anda akan menemui teknik biasa untuk mewakili masalah pada komputer kuantum, mempelajari bagaimana kaedah kuantum dan klasik berfungsi bersama, dan mula mengenal pasti alat serta pertukaran yang penting untuk pelbagai jenis masalah."}),"\n",(0,t.jsx)(n.p,{children:"Dalam pelajaran pertama ini, kita akan merangkumi beberapa konsep asas dan istilah yang membantu anda memahami aplikasi pengkomputeran kuantum pada peringkat tinggi, dan memberikan gambaran keseluruhan bidang aplikasi utama yang sedang diteroka secara aktif oleh komuniti saintifik."}),"\n",(0,t.jsx)(n.h2,{id:"what-quantum-computers-might-be-useful-for",children:"Untuk apa komputer kuantum mungkin berguna"}),"\n",(0,t.jsx)(n.p,{children:"Komputer kuantum sering digambarkan sebagai pesaing kepada komputer klasik, tetapi cara yang lebih sesuai untuk memikirkannya ialah sebagai sumber khusus dalam aliran kerja klasik yang lebih besar. Persoalan pentingnya ialah bahagian pengiraan yang manakah sangat sesuai untuk perkakasan kuantum. Jawapan yang paling intuitif datang daripada masalah yang sememangnya kuantum, seperti kelakuan molekul, bahan, dan medan kuantum. Pemproses kuantum boleh mewakili dan memanipulasi keadaan kuantum secara langsung, manakala sumber yang diperlukan untuk huraian klasik umum bertambah secara eksponen dengan saiz sistem."}),"\n",(0,t.jsx)(n.p,{children:"Kes ini lebih halus bagi masalah dengan input dan output klasik, tetapi masih ada sebab yang baik untuk meneroka masalah tersebut. Masalah pengoptimuman adalah meluas dan penting dari segi ekonomi, jadi peningkatan yang sederhana dalam kualiti penyelesaian atau masa larian pun boleh bernilai. Algoritma kuantum juga mungkin menawarkan cara baharu untuk meneroka ruang penyelesaian yang rumit atau memanfaatkan struktur dalam kelas masalah tertentu. Pembelajaran mesin kuantum mempunyai motivasi teori yang kukuh untuk masalah tertentu dengan input klasik, termasuk klasifikasi berstruktur dan pemprosesan set data yang sangat besar. Walau bagaimanapun, sama ada hasil ini boleh diterjemahkan kepada kelebihan praktikal pada data klasik dunia sebenar masih menjadi persoalan terbuka. Persamaan pembezaan separa menghuraikan banyak sistem penting dalam sains, kejuruteraan, dan kewangan, dan algoritma kuantum mungkin memperbaiki penskalaan simulasi berdimensi tinggi tertentu dan masalah algebra linear yang besar."}),"\n",(0,t.jsx)(n.p,{children:"Dalam ketiga-tiga bidang ini, bagaimanapun, kos menyediakan input klasik, menjalankan pengiraan kuantum, dan mengekstrak jawapan klasik yang berguna boleh melebihi manfaat langkah kuantum. Kita akan mengingati cabaran praktikal ini semasa meneroka bagaimana kaedah kuantum digunakan dalam setiap bidang."}),"\n",(0,t.jsx)(n.h2,{id:"near-term-quantum-utility-and-advantage",children:"Utiliti dan kelebihan kuantum jangka dekat"}),"\n",(0,t.jsx)(n.p,{children:"Kursus ini bukan secara khusus tentang kelebihan kuantum, tetapi perbincangan tentang kelebihan kuantum tidak dapat dielakkan. Motivasi asas di sebalik aplikasi kuantum ialah menggunakan sumber kuantum untuk melanjutkan apa yang komputer klasik boleh lakukan sendiri: menghasilkan keputusan yang lebih tepat, mencapai penyelesaian dengan lebih pantas, atau menyelesaikan masalah yang sebaliknya tidak dapat dicapai. Istilah berkaitan berikut membantu kita bercakap dengan jelas tentang kemajuan yang kita lihat:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Pecutan kuantum:"})," Apabila saiz masalah bertambah, masa yang diperlukan oleh kaedah kuantum meningkat dengan lebih baik berbanding kaedah klasik terbaik yang relevan untuk tugas yang sama."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Kelebihan kuantum:"})," Pengiraan berbantukan kuantum mengatasi pendekatan klasik terbaik yang relevan pada tugas yang jelas takrifannya dan metrik yang bermakna. Bukannya satu pencapaian tunggal yang kekal, kelebihan kuantum ialah sempadan yang berkembang dan beralih apabila kedua-dua kaedah kuantum dan klasik bertambah baik."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Utiliti kuantum:"})," Pengiraan kuantum menyumbang kepada hasil saintifik atau teknikal yang berguna. Ia beroperasi pada skala, kedalaman, dan ketepatan di luar simulasi klasik daya kasar yang praktikal, tanpa semestinya mengatasi kaedah klasik terbaik."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Algoritma jangka dekat:"})," Algoritma yang direka untuk pemproses kuantum semasa, menggunakan kedalaman litar yang terhad dan sering bergantung pada pasca-pemprosesan klasik dan pengurangan ralat berbanding pembetulan ralat kuantum penuh."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Pengkomputeran kuantum bertoleransi kerosakan:"})," Pada masa hadapan, pengkomputeran kuantum akan menggunakan pembetulan ralat kuantum untuk melindungi qubit logik sepanjang pengiraan. Apabila kadar ralat fizikal berada di bawah ambang toleransi kerosakan, sumber pembetulan ralat tambahan boleh menekan ralat logik ke tahap yang diperlukan oleh pengiraan yang panjang dan boleh dipercayai. Toleransi kerosakan membolehkan algoritma yang jauh lebih dalam, termasuk pelaksanaan berskala besar algoritma Shor."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Toleransi kerosakan awal:"})," Toleransi kerosakan bermaksud ralat ditekan, bukan dihapuskan sepenuhnya. Dalam sistem bertoleransi kerosakan awal, ralat logik baki masih perlu diambil kira, dan kedalaman litar yang boleh dipercayai kekal terhad."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"Algoritma heuristik:"})," Kaedah yang direka untuk mencari penyelesaian yang baik dalam amalan tanpa menjamin jawapan optimum atau masa larian tertentu."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.h2,{id:"a-brief-foundation-in-complexity-theory",children:"Asas ringkas dalam teori kerumitan"}),"\n",(0,t.jsx)(n.p,{children:"Dalam sesetengah bidang aplikasi, kita mempunyai sebab teori yang kukuh untuk menjangkakan bahawa komputer kuantum mungkin mempunyai kelebihan. Untuk memahami dari mana keyakinan ini datang, kita memerlukan sedikit perbendaharaan kata daripada teori kerumitan."}),"\n",(0,t.jsx)(n.p,{children:"Teori kerumitan mengkaji bagaimana sumber yang diperlukan untuk menyelesaikan masalah bertambah apabila masalah menjadi lebih besar. Ia memberi kita peta yang berguna tentang di mana pecutan kuantum mungkin dapat dicapai. Beberapa istilah amat penting untuk kursus ini:"}),"\n",(0,t.jsxs)(n.ul,{children:["\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"P:"})," Masalah yang boleh diselesaikan dengan cekap oleh komputer klasik, bermaksud sumber yang diperlukan bertambah secara polinomial dengan saiz masalah."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP:"})," Masalah yang penyelesaian yang dicadangkan boleh disemak dengan cekap, walaupun mencari penyelesaian itu mungkin sangat sukar."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-hard:"})," Masalah yang sekurang-kurangnya sama sukar dengan setiap masalah dalam NP. Masalah NP-hard tidak semestinya tergolong dalam NP. Banyak masalah pengoptimuman ialah NP-hard."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"NP-complete:"})," Masalah yang kedua-duanya NP-hard dan berada dalam NP. Ini ialah masalah keputusan yang paling sukar dalam NP."]}),"\n"]}),"\n",(0,t.jsxs)(n.li,{children:["\n",(0,t.jsxs)(n.p,{children:[(0,t.jsx)(n.strong,{children:"BQP:"})," Masalah yang boleh diselesaikan dengan cekap oleh komputer kuantum dengan kebarangkalian ralat yang terbatas."]}),"\n"]}),"\n"]}),"\n",(0,t.jsx)(n.p,{children:"Sesetengah hubungan antara kategori ini diketahui. P terkandung dalam kedua-dua NP dan BQP kerana masalah yang boleh diselesaikan dengan cekap pada komputer klasik juga boleh disemak secara klasik dan diselesaikan pada komputer kuantum. Hubungan lain masih terbuka. Kita tidak tahu sama ada P sama dengan NP atau sama ada NP terkandung dalam BQP. Walau bagaimanapun, penyelidik umumnya percaya bahawa P lebih kecil daripada kedua-dua NP dan BQP, dan bahawa komputer kuantum tidak dapat menyelesaikan setiap masalah NP-complete dengan cekap. Secara mudah, komputer kuantum bukanlah kotak ajaib yang serta-merta menyelesaikan setiap masalah sukar."}),"\n",(0,t.jsx)(n.p,{children:"Hujah berasaskan kerumitan yang paling kukuh untuk pengkomputeran kuantum terpakai pada jenis masalah tertentu. Algoritma Shor berskala jauh lebih baik daripada algoritma klasik terbaik yang diketahui untuk pemfaktoran dan logaritma diskret, walaupun pemfaktoran belum terbukti berada di luar P. Simulasi kuantum am juga mempunyai asas teori yang kukuh. Sesetengah masalah simulasi kuantum ialah BQP-complete, bermaksud menyelesaikannya secara klasik dengan cekap akan setara dengan mensimulasikan sebarang pengiraan kuantum dengan cekap. Simulasi klasik yang cekap sedemikian sangat tidak munasabah, dan ini salah satu sebab simulasi Hamiltonian kuantum dianggap sebagai bidang aplikasi yang begitu menjanjikan."}),"\n",(0,t.jsx)(n.p,{children:"Sesetengah PDE berdimensi tinggi boleh dikurangkan kepada masalah sistem linear BQP-complete, memberi kita sebab yang kukuh untuk menjangkakan pecutan kuantum apabila input dan output dapat dikendalikan dengan cekap. QML mempunyai contoh yang serupa: sesetengah tugas yang melibatkan data kuantum ialah BQP-complete, dan sesetengah model kuantum boleh menjana sampel yang sukar dihasilkan semula secara klasik."}),"\n",(0,t.jsx)(n.p,{children:"Kesnya kurang mudah bagi pengoptimuman. Komputer kuantum tidak dijangka menyelesaikan masalah NP-hard sewenang-wenangnya dengan cekap, tetapi ia mungkin masih membantu dengan masalah berstruktur, kejadian tertentu, atau langkah khusus dalam aliran kerja pengoptimuman. Algoritma Grover, sebagai contoh, memberikan pecutan kuadratik untuk carian tidak berstruktur. Itu ialah peningkatan yang bermakna, walaupun punca kuasa dua bagi ruang carian yang sangat besar masih boleh menjadi sangat besar."}),"\n",(0,t.jsx)(n.h2,{id:"from-complexity-theory-to-practical-evidence",children:"Daripada teori kerumitan kepada bukti praktikal"}),"\n",(0,t.jsx)(n.p,{children:"Teori kerumitan boleh memberitahu kita di mana pecutan kuantum mungkin dapat dicapai, tetapi ia biasanya tidak dapat memberitahu kita bagaimana sesuatu kaedah berprestasi pada masalah tertentu atau komputer kuantum tertentu. Banyak kaedah yang digunakan pada perkakasan semasa adalah heuristik. Ia direka untuk mencari jawapan yang baik dalam amalan, tetapi tidak menjamin jawapan terbaik yang mungkin atau masa larian tertentu."}),"\n",(0,t.jsx)(n.p,{children:"Heuristik bukan unik kepada pengkomputeran kuantum, dan menggelar sesuatu kaedah sebagai heuristik tidak bermakna ia tidak boleh dipercayai atau tidak saintifik. Pengoptimuman klasik, pembelajaran mesin, dan kimia pengiraan semuanya sangat bergantung pada heuristik apabila penyelesaian tepat terlalu mahal. Heuristik kuantum mungkin menawarkan cara baharu untuk meneroka ruang penyelesaian, menyediakan keadaan yang berguna, atau mengenal pasti calon yang menjanjikan. Sama ada ia berfungsi dengan baik ialah persoalan empirikal: kita perlu menjalankannya dan mengukur hasilnya."}),"\n",(0,t.jsx)(n.p,{children:"Oleh sebab heuristik tidak disertakan dengan jaminan prestasi, kita menilainya menggunakan metrik kejayaan yang jelas, garis dasar klasik yang kukuh, dan ujian merentasi saiz masalah yang berbeza. Ini membantu kita melihat di mana sesuatu kaedah berfungsi dengan baik dan bagaimana prestasinya berubah apabila masalah diskalakan."}),"\n",(0,t.jsx)(n.h2,{id:"application-areas-and-course-case-studies",children:"Bidang aplikasi dan kajian kes kursus"}),"\n",(0,t.jsx)(n.p,{children:"Kita menyusun kursus ini sekitar empat bidang aplikasi yang luas. Ia tidak merangkumi setiap kegunaan komputer kuantum yang mungkin, tetapi ia memberi kita cara yang berguna untuk membandingkan di mana hujah yang paling kukuh berada dan di mana persoalan terbuka berada."}),"\n",(0,t.jsx)(n.h3,{id:"hamiltonian-simulation",children:"Simulasi Hamiltonian"}),"\n",(0,t.jsx)(n.p,{children:"Simulasi Hamiltonian merangkumi menganggar tenaga, mengkaji sifat kimia dan bahan, dan memodelkan bagaimana sistem kuantum berubah mengikut masa. Ia merentasi kimia, sains bahan, fizik jirim terpeka, dan fizik tenaga tinggi dan nuklear. Kajian kes kita meneliti model besi-sulfur berkorelasi kuat menggunakan pepenjuruan kuantum berasaskan sampel dan mensimulasikan dinamik hadron menggunakan perwakilan kekisi yang peka terhadap simetri. Ini ialah dua contoh daripada bidang yang jauh lebih besar, yang turut merangkumi mekanisme tindak balas, bahan magnet, dan dinamik banyak jasad yang lain."}),"\n",(0,t.jsx)(n.h3,{id:"optimization",children:"Pengoptimuman"}),"\n",(0,t.jsx)(n.p,{children:"Pengoptimuman muncul di mana-mana daripada kewangan dan logistik hingga penjadualan dan sistem tenaga. Ia juga bidang yang kelebihan sukar dibuktikan, kerana penyelesai klasik sangat berkebolehan dan pemetaan kuantum boleh menambah overhed yang mahal. Kajian kes kita menggunakan pemilihan portfolio untuk meneroka bagaimana masalah pengoptimuman diwakili, dijalankan, dan ditanda aras tanpa mengandaikan bahawa komputer kuantum secara automatik mencari optimum yang tepat."}),"\n",(0,t.jsx)(n.h3,{id:"quantum-machine-learning",children:"Pembelajaran mesin kuantum"}),"\n",(0,t.jsx)(n.p,{children:"Pembelajaran mesin kuantum menyoal sama ada litar kuantum atau data kuantum boleh memperbaiki tugas pembelajaran. Persoalan penting termasuk pengekodan data, kos latihan, generalisasi, dan perbandingan dengan model klasik yang kukuh."}),"\n",(0,t.jsx)(n.h3,{id:"partial-differential-equations",children:"Persamaan pembezaan separa"}),"\n",(0,t.jsx)(n.p,{children:"Persamaan pembezaan separa menghuraikan sistem seperti bendalir, haba, dan gelombang. Algoritma kuantum mungkin mempercepat bahagian sesetengah aliran kerja PDE, tetapi penyediaan data dan pengekstrakan jawapan klasik yang berguna boleh menjadi kos utama. Kajian kes khusus masih sedang dibangunkan."}),"\n",(0,t.jsx)(n.p,{children:"Dalam pelajaran seterusnya, kita akan mengemukakan soalan asas yang sama dalam setiap bidang: Apakah masalahnya, mengapa pengkomputeran kuantum mungkin membantu, apakah batasannya, dan apakah yang sebenarnya ditunjukkan oleh bukti? Kita akan bermula dengan simulasi Hamiltonian, di mana masalah itu sendiri bersifat kuantum."}),"\n",(0,t.jsx)(n.h2,{id:"conclusion",children:"Kesimpulan"}),"\n",(0,t.jsx)(n.p,{children:"Kita telah merangkumi banyak perkara, tetapi idea utamanya mudah: komputer kuantum ialah alat khusus, dan nilainya bergantung pada penggunaan kaedah kuantum yang betul untuk masalah yang betul atau bahagian masalah yang lebih besar. Simulasi Hamiltonian mempunyai asas teori yang paling jelas, pengoptimuman mempunyai set kaedah heuristik dan tanda aras yang matang, dan QML serta PDE menawarkan hala tuju menjanjikan yang masih berkembang."}),"\n",(0,t.jsx)(n.p,{children:"Dalam pelajaran seterusnya, kita akan beralih daripada gambaran keseluruhan yang luas ini kepada contoh praktikal. Untuk setiap aplikasi, kita akan menyoal masalah apa yang cuba diselesaikan, apakah peranan komputer kuantum, bagaimana hasil ditafsirkan, dan apa yang boleh kita pelajari daripadanya. Matlamatnya ialah membina gerak hati anda tentang di mana pengkomputeran kuantum mungkin membantu dan apa yang diperlukan untuk menukar idea yang menjanjikan kepada pengiraan sebenar."}),"\n"]})}function d(a={}){const{wrapper:n}={...(0,u.R)(),...a.components};return n?(0,t.jsx)(n,{...a,children:(0,t.jsx)(l,{...a})}):l(a)}},28453(a,n,e){e.d(n,{R:()=>k,x:()=>r});var i=e(96540);const t={},u=i.createContext(t);function k(a){const n=i.useContext(u);return i.useMemo(function(){return"function"==typeof a?a(n):{...n,...a}},[n,a])}function r(a){let n;return n=a.disableParentContext?"function"==typeof a.components?a.components(t):a.components||t:k(a.components),i.createElement(u.Provider,{value:n},a.children)}}}]);